import AppKit

/// Polls NSPasteboard.changeCount and feeds new, non-sensitive content into the store.
@MainActor
final class ClipboardMonitor {
    private let store: ClipboardStore
    private var timer: Timer?
    private var lastCount = NSPasteboard.general.changeCount

    private static let ignoredTypes: Set<String> = [
        "org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType", "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
    ]

    init(store: ClipboardStore) { self.store = store }

    func start() {
        guard timer == nil else { return }
        lastCount = NSPasteboard.general.changeCount
        let t = Timer(timeInterval: 0.5, repeats: true) { [weak self] _ in
            MainActor.assumeIsolated { self?.poll() }
        }
        t.tolerance = 0.15
        RunLoop.main.add(t, forMode: .common)
        timer = t
    }

    func stop() { timer?.invalidate(); timer = nil }

    private func poll() {
        let pb = NSPasteboard.general
        let cc = pb.changeCount
        guard cc != lastCount else { return }
        lastCount = cc
        if cc == store.ownChangeCount { return }

        let types = (pb.types ?? []).map(\.rawValue)
        if types.contains(where: { Self.ignoredTypes.contains($0) || $0.hasPrefix("com.agilebits.onepassword") }) { return }
        let app = NSWorkspace.shared.frontmostApplication
        if let b = app?.bundleIdentifier, ClipPrefs.excluded.contains(b) { return }

        if let urls = pb.readObjects(forClasses: [NSURL.self], options: [.urlReadingFileURLsOnly: true]) as? [URL], !urls.isEmpty {
            let text = urls.map(\.path).joined(separator: "\n")
            store.addText(text, kind: .file, smart: .path, app: app)
            return
        }
        let hasString = pb.string(forType: .string) != nil
        if !hasString, let tiff = pb.data(forType: .tiff) ?? pngAsTIFF(pb) {
            let weakSelf = self
            Task.detached(priority: .utility) {
                guard let r = ClipboardStore.encodePNG(fromTIFF: tiff) else { return }
                await MainActor.run { weakSelf.store.addImage(png: r.png, width: r.w, height: r.h, hash: r.hash, app: app) }
            }
            return
        }
        if let s = pb.string(forType: .string) {
            guard !s.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty, s.count <= 500_000 else { return }
            let smart = ClipDetect.classify(s)
            let kind: ClipKind = (smart == .url || smart == .deeplink) ? .url : (smart == .hexColor ? .color : .text)
            store.addText(s, kind: kind, smart: smart, app: app)
            return
        }
        if let c = (pb.readObjects(forClasses: [NSColor.self]) as? [NSColor])?.first, let rgb = c.usingColorSpace(.sRGB) {
            let hex = String(format: "#%02X%02X%02X", Int(round(rgb.redComponent * 255)), Int(round(rgb.greenComponent * 255)), Int(round(rgb.blueComponent * 255)))
            store.addText(hex, kind: .color, smart: .hexColor, app: app)
        }
    }

    private func pngAsTIFF(_ pb: NSPasteboard) -> Data? {
        guard let png = pb.data(forType: .png), let rep = NSBitmapImageRep(data: png) else { return nil }
        return rep.tiffRepresentation
    }
}
